declare(strict_types=1);namespace Pam\Native\Observability;use InvalidArgumentException;use Throwable;final class Observability{private array$queue=[];private int$dropped=0;private array$context=[];public function __construct(private readonly ObservabilityConfig$config,private readonly TelemetryTransport$transport){}public function context(array$values):void{$this->context=$this->clean($values);}public function span(string$name,?Span$parent=null):Span{if(!preg_match('/^[^\x00-\x1f]{1,200}$/u',$name))throw new InvalidArgumentException('Invalid span name.');return new Span($this,$name,$parent?->traceId??bin2hex(random_bytes(16)),bin2hex(random_bytes(8)),$parent?->spanId,hrtime(true));}public function log(Severity$severity,string$message,array$attributes=[]):void{$this->enqueue(SignalKind::Log,['severity'=>$severity->value,'message'=>substr($message,0,8192),'attributes'=>$this->clean($attributes)]);}public function counter(string$name,int|float$value=1,array$attributes=[]):void{$this->metric(SignalKind::Counter,$name,$value,$attributes);}public function gauge(string$name,int|float$value,array$attributes=[]):void{$this->metric(SignalKind::Gauge,$name,$value,$attributes);}public function crash(Throwable$error,bool$handled=false):void{$this->enqueue(SignalKind::Crash,['handled'=>$handled,'exception'=>['type'=>$error::class,'message'=>substr($error->getMessage(),0,4096),'file'=>$error->getFile(),'line'=>$error->getLine(),'trace'=>substr($error->getTraceAsString(),0,16000)]]);}public function finishSpan(Span$span,int$start,int$end,SpanStatus$status,array$attributes):void{if(!$this->sample($span->traceId))return;$this->enqueue(SignalKind::Span,['name'=>$span->name,'traceId'=>$span->traceId,'spanId'=>$span->spanId,'parentSpanId'=>$span->parentSpanId,'startUnixNano'=>$this->unixNano($start),'endUnixNano'=>$this->unixNano($end),'status'=>$status->value,'attributes'=>$this->clean($attributes)]);}public function flush():int{$sent=0;while($this->queue!==[]){$batch=array_splice($th